insert into users(id,name,age,points,streak) values (1,'Maya',9,1240,7) on conflict(id) do update set name=excluded.name, age=excluded.age, points=excluded.points, streak=excluded.streak;
insert into talents(slug,name,name_ar,description,description_ar,category,category_ar,icon,accent,total_lessons) values
('creative-arts','Creative Arts','الفنون الإبداعية','Turn big feelings into bold colors, stories, and beautiful ideas.','حوّل مشاعرك وأفكارك إلى ألوان وقصص وابتكارات جميلة.','Expression','تعبير','✦','coral',8),
('young-inventors','Young Inventors','المخترعون الصغار','Ask why, build prototypes, and make everyday things smarter.','اسأل لماذا، ابنِ نماذج أولية، واجعل الأشياء اليومية أذكى.','Build & solve','ابتكار وحل','⌁','cyan',10),
('story-lab','Story Lab','مختبر الحكايات','Find your voice through characters, words, and curious worlds.','اكتشف صوتك من خلال الشخصيات والكلمات والعوالم المدهشة.','Communication','تواصل','◌','lime',6),
('move-and-groove','Move & Groove','الحركة والإيقاع','Explore rhythm, coordination, and the joy of moving your way.','استكشف الإيقاع والتناسق ومتعة الحركة بطريقتك.','Energy','طاقة','↗','violet',7)
insert into progress_records(user_id,talent_slug,completed_lessons,total_lessons) values (1,'creative-arts',5,8),(1,'young-inventors',2,10) on conflict(user_id,talent_slug) do update set completed_lessons=excluded.completed_lessons,total_lessons=excluded.total_lessons;
insert into achievements(user_id,title,title_ar,icon) values (1,'First Spark','الشرارة الأولى','✦'),(1,'Creative Explorer','مستكشف الإبداع','◌'),(1,'Seven Day Streak','سلسلة سبعة أيام','🔥'),(1,'Curious Mind','عقل فضولي','⌁');
insert into notifications(user_id,title,body) values (1,'Your next spark is waiting.','You are one lesson away from your next badge.'),(1,'New path unlocked','Try Young Inventors next.');
insert into assessment_questions(id,prompt,prompt_ar,options) values
(1,'When you have a free afternoon, what sounds most exciting?','عندما يكون لديك وقت فراغ، ما الشيء الأكثر إثارة؟','[{"label":"Making something colorful","labelAr":"صنع شيء مليء بالألوان","talent":"creative-arts"},{"label":"Building a clever solution","labelAr":"بناء حل ذكي","talent":"young-inventors"},{"label":"Writing a mini adventure","labelAr":"كتابة مغامرة صغيرة","talent":"story-lab"},{"label":"Trying a new movement","labelAr":"تجربة حركة جديدة","talent":"move-and-groove"}]'),
(2,'A tricky challenge makes you want to…','التحدي الصعب يجعلك تريد أن…','[{"label":"Sketch a few possibilities","labelAr":"ترسم بعض الاحتمالات","talent":"creative-arts"},{"label":"Test how it works","labelAr":"تختبر كيف يعمل","talent":"young-inventors"},{"label":"Explain it with a story","labelAr":"تشرحه من خلال قصة","talent":"story-lab"},{"label":"Act it out","labelAr":"تمثله بحركة","talent":"move-and-groove"}]'),
(3,'Which compliment feels most like you?','أي مجاملة تشبهك أكثر؟','[{"label":"You notice beautiful details","labelAr":"تلاحظ التفاصيل الجميلة","talent":"creative-arts"},{"label":"You never give up on a puzzle","labelAr":"لا تستسلم أمام الألغاز","talent":"young-inventors"},{"label":"You make ideas easy to understand","labelAr":"تجعل الأفكار سهلة الفهم","talent":"story-lab"},{"label":"You bring energy to the room","labelAr":"تضيف طاقة للمكان","talent":"move-and-groove"}]'),
(4,'What would you add to your dream clubhouse?','ماذا ستضيف إلى نادي أحلامك؟','[{"label":"A giant art wall","labelAr":"حائط فنون كبير","talent":"creative-arts"},{"label":"A gadget workshop","labelAr":"ورشة أدوات ذكية","talent":"young-inventors"},{"label":"A shelf of magical books","labelAr":"رف كتب سحرية","talent":"story-lab"},{"label":"A music and movement floor","labelAr":"مساحة موسيقى وحركة","talent":"move-and-groove"}]'),
(5,'When you learn something new, you prefer to…','عندما تتعلم شيئًا جديدًا، تفضّل أن…','[{"label":"See it and make it","labelAr":"تراه وتصنعه","talent":"creative-arts"},{"label":"Take it apart and rebuild it","labelAr":"تفككه وتعيد بناءه","talent":"young-inventors"},{"label":"Talk it through","labelAr":"تتحدث عنه","talent":"story-lab"},{"label":"Practice it with your body","labelAr":"تتدرب عليه بجسمك","talent":"move-and-groove"}]')
